from pathlib import Path
r=Path(__file__).parent/'runtime'
p=r/'web/services/chains.py';s=p.read_text().replace('from core.video import production, content_columns, store, autopilot_store as ap','from core.video import production, content_columns, store, recipes, autopilot_store as ap')
s=s.replace("outputs.append({**p.as_dict(),'effective_render':", "recipe=recipes.find(paths().config_dir,p.recipe)\n            outputs.append({**p.as_dict(),'audiences':list(recipe.audiences) if recipe else [],'effective_render':")
s=s.replace("recipe['audiences']=[audience]", "recipe['audiences']=[audience]+[a for a in ('non_tech','developer') if a!=audience]\n        recipe['minutes_range']=[0.5,10]")
s=s.replace("            if 'auto' in o:data['auto']=int(bool(o['auto']))", "            if 'auto' in o:data['auto']=int(bool(o['auto']))\n            for setting in ('minutes','audience'):\n                if setting in o:data[setting]=o[setting]")
s=s.replace("            production._write(paths().config_dir,o['key'],data)", "            production._write(paths().config_dir,o['key'],data)\n            changed=production.get(paths().config_dir,paths().jobs_dir,o['key'])\n            if changed.errors:error('；'.join(changed.errors),422)")
p.write_text(s)
p=r/'ui/src/pages/Chains.tsx';s=p.read_text();s=s.replace('type Output = {','type Output = {recipe:string;base_recipe:string;audience_key:string;audiences:string[];target_minutes:number;minutes_range:number[];')
s=s.replace("  const [preview,setPreview]", "  const [voices,setVoices]=useState<{id:string;label:string}[]>([]);\n  const [preview,setPreview]")
s=s.replace("function beginEdit(){if(!data)return;", "function beginEdit(){if(!data)return;void api<{voices:{id:string;label:string}[]}>('/api/video/autovideo').then(x=>setVoices(x.voices)).catch(()=>{});")
s=s.replace("各输出的自动制作与速度", "各输出的观众、时长、声音与速度")
s=s.replace("<span className=\"flex-1\">{o.name}</span><label>", "<span className=\"w-full font-medium\">{o.name}</span>{o.audiences?.length>1&&<label>观众<select className=\"input\" value={o.audience_key} onChange={e=>setDraft({...draft,outputs:draft.outputs.map((x,j)=>j===i?{...x,audience_key:e.target.value}:x)})}>{o.audiences.map(a=><option key={a} value={a}>{a==='non_tech'?'普通观众':a==='developer'?'开发者':a}</option>)}</select></label>}{o.minutes_range?.length===2&&<label>目标时长<select className=\"input\" value={o.target_minutes} onChange={e=>setDraft({...draft,outputs:draft.outputs.map((x,j)=>j===i?{...x,target_minutes:Number(e.target.value)}:x)})}>{Array.from(new Set([o.target_minutes,...Array.from({length:Math.floor((o.minutes_range[1]-o.minutes_range[0])*2)+1},(_,n)=>o.minutes_range[0]+n*.5)])).sort((a,b)=>a-b).map(n=><option key={n} value={n}>{n} 分钟</option>)}</select></label>}<label>声音<select className=\"input\" value={String(o.render.voice_id||'')} onChange={e=>setDraft({...draft,outputs:draft.outputs.map((x,j)=>{if(j!==i)return x;const render={...x.render};if(e.target.value)render.voice_id=e.target.value;else delete render.voice_id;return {...x,render}})})}><option value=\"\">继承默认声音</option>{voices.map(v=><option key={v.id} value={v.id}>{v.label}</option>)}</select></label><label>")
s=s.replace("outputs:draft.outputs.map(o=>({key:o.key,auto:o.auto,render:o.render}))", "outputs:draft.outputs.map(o=>({key:o.key,auto:o.auto,render:o.render,...(o.target_minutes!==data.outputs_detail.find(x=>x.key===o.key)?.target_minutes?{minutes:o.target_minutes}:{}),...(o.audience_key!==data.outputs_detail.find(x=>x.key===o.key)?.audience_key?{audience:o.audience_key}:{})}))")
s=s.replace("<details className=\"text-xs text-text-muted mt-2\"><summary>查看实际生效设置</summary>", "<p className=\"text-xs text-text-muted mt-1\">目标时长约 {o.target_minutes} 分钟 · <Link className=\"text-accent\" to={link('/video-recipes/'+encodeURIComponent(o.base_recipe))}>文稿与画面配方</Link></p><details className=\"text-xs text-text-muted mt-2\"><summary>查看实际生效设置</summary>")
p.write_text(s)
